import{_ as n,a0 as d,w as r,s as p,ao as o,I as i,a1 as l,A as s,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Fedora 下使用下拉式终端更快输入命令 | LCTT x X-CMD","titleTemplate":false,"description":"在 Fedora 下使用下拉式终端更快输入命令 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Fedora 下使用下拉式终端更快输入命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Fedora 下使用下拉式终端更快输入命令 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190809 Use a drop-down terminal for fast commands in Fedora","title":"在 Fedora 下使用下拉式终端更快输入命令","tag":"201908","desc":""},"relativePath":"201908/20190809 Use a drop-down terminal for fast commands in Fedora.md","filePath":"[post].md"}'),g={name:"201908/20190809 Use a drop-down terminal for fast commands in Fedora.md"};function u(k,a,h,f,m,b){const t=d("Link");return r(),p("div",null,[a[28]||(a[28]=o('<h1 id="在-fedora-下使用下拉式终端更快输入命令" tabindex="-1">在 Fedora 下使用下拉式终端更快输入命令 <a class="header-anchor" href="#在-fedora-下使用下拉式终端更快输入命令" aria-label="Permalink to “在 Fedora 下使用下拉式终端更快输入命令”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/dropdown-terminals-816x345.jpg" alt=""></p><p>下拉式终端可以一键打开，并快速输入桌面上的任何命令。通常它会以平滑的方式创建终端，有时会带有下拉效果。本文演示了如何使用 Yakuake、Tilda、Guake 和 GNOME 扩展等下拉式终端来改善和加速日常任务。</p><h3 id="yakuake" tabindex="-1">Yakuake <a class="header-anchor" href="#yakuake" aria-label="Permalink to “Yakuake”">​</a></h3>',4)),i("p",null,[l(t,{href:"https://kde.org/applications/system/org.kde.yakuake"},{default:s(()=>[...a[0]||(a[0]=[e("Yakuake",-1)])]),_:1}),a[1]||(a[1]=e(" 是一个基于 KDE Konsole 技术的下拉式终端模拟器。它以 GNU GPLv2 条款分发。它包括以下功能：",-1))]),a[29]||(a[29]=o('<ul><li>从屏幕顶部平滑地滚下</li><li>标签式界面</li><li>尺寸和动画速度可配置</li><li>换肤</li><li>先进的 D-Bus 接口</li></ul><p>要安装 Yakuake，请使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install -y yakuake</span></span></code></pre></div><h4 id="启动和配置" tabindex="-1">启动和配置 <a class="header-anchor" href="#启动和配置" aria-label="Permalink to “启动和配置”">​</a></h4><p>如果你运行 KDE，请打开系统设置，然后转到“启动和关闭”。将“yakuake”添加到“自动启动”下的程序列表中，如下所示：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/auto_start-1024x723.png" alt=""></p><p>Yakuake 运行时很容易配置，首先在命令行启动该程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yakuake &amp;</span></span></code></pre></div><p>随后出现欢迎对话框。如果标准的快捷键和你已经使用的快捷键冲突，你可以设置一个新的。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/yakuake_config-1024x419.png" alt=""></p><p>点击菜单按钮，出现如下帮助菜单。接着，选择“配置 Yakuake……”访问配置选项。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/yakuake_config_01.png" alt=""></p><p>你可以自定义外观选项，例如透明度、行为（例如当鼠标指针移过它们时聚焦终端）和窗口（如大小和动画）。在窗口选项中，你会发现当你使用两个或更多监视器时最有用的选项之一：“在鼠标所在的屏幕上打开”。</p><h4 id="使用-yakuake" tabindex="-1">使用 Yakuake <a class="header-anchor" href="#使用-yakuake" aria-label="Permalink to “使用 Yakuake”">​</a></h4><p>主要的快捷键有：</p><ul><li><code>F12</code> = 打开/撤回 Yakuake</li><li><code>Ctrl+F11</code> = 全屏模式</li><li><code>Ctrl+)</code> = 上下分割</li><li><code>Ctrl+(</code> = 左右分割</li><li><code>Ctrl+Shift+T</code> = 新会话</li><li><code>Shift+Right</code> = 下一个会话</li><li><code>Shift+Left</code> = 上一个会话</li><li><code>Ctrl+Alt+S</code> = 重命名会话</li></ul>',16)),i("p",null,[a[3]||(a[3]=e("以下是 Yakuake 像",-1)),l(t,{href:"https://fedoramagazine.org/4-cool-terminal-multiplexers/"},{default:s(()=>[...a[2]||(a[2]=[e("终端多路复用器",-1)])]),_:1}),a[4]||(a[4]=e("一样分割会话的示例。使用此功能，你可以在一个会话中运行多个 shell。",-1))]),a[30]||(a[30]=i("p",null,[i("img",{src:"https://fedoramagazine.org/wp-content/uploads/2019/07/yakuake_usage.gif",alt:""})],-1)),a[31]||(a[31]=i("h3",{id:"tilda",tabindex:"-1"},[e("Tilda "),i("a",{class:"header-anchor",href:"#tilda","aria-label":"Permalink to “Tilda”"},"​")],-1)),i("p",null,[l(t,{href:"https://github.com/lanoxx/tilda"},{default:s(()=>[...a[5]||(a[5]=[e("Tilda",-1)])]),_:1}),a[6]||(a[6]=e(" 是一个下拉式终端，可与其他流行的终端模拟器相媲美，如 GNOME 终端、KDE 的 Konsole、xterm 等等。",-1))]),a[32]||(a[32]=o('<p>它具有高度可配置的界面。你甚至可以更改终端大小和动画速度等选项。Tilda 还允许你启用热键，以绑定到各种命令和操作。</p><p>要安装 Tilda，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install -y tilda</span></span></code></pre></div><h4 id="启动和配置-1" tabindex="-1">启动和配置 <a class="header-anchor" href="#启动和配置-1" aria-label="Permalink to “启动和配置”">​</a></h4><p>大多数用户更喜欢在登录时就在后台运行一个下拉式终端。要设置此选项，请首先转到桌面上的应用启动器，搜索 Tilda，然后将其打开。</p><p>接下来，打开 Tilda 配置窗口。 选择“隐藏启动 Tilda”，即启动时不会立即显示终端。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/tilda_startup.png" alt=""></p><p>接下来，你要设置你的桌面自动启动 Tilda。如果你使用的是 KDE，请转到“系统设置 &gt; 启动与关闭 &gt; 自动启动”并“添加一个程序”。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/tilda_startup_alt.png" alt=""></p><p>如果你正在使用 GNOME，则可以在终端中运行此命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ln -s /usr/share/applications/tilda.desktop ~/.config/autostart/</span></span></code></pre></div><p>当你第一次运行它时，会出现一个向导来设置首选项。如果需要更改设置，请右键单击终端并转到菜单中的“首选项”。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/tilda_config.png" alt=""></p><p>你还可以创建多个配置文件，并绑定其他快捷键以在屏幕上的不同位置打开新终端。为此，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tilda -C</span></span></code></pre></div><p>每次使用上述命令时，Tilda 都会在名为 <code>~/.config/tilda/</code> 文件夹中创建名为 <code>config_0</code>、<code>config_1</code> 之类的新配置文件。然后，你可以映射组合键以打开具有一组特定选项的新 Tilda 终端。</p><h4 id="使用-tilda" tabindex="-1">使用 Tilda <a class="header-anchor" href="#使用-tilda" aria-label="Permalink to “使用 Tilda”">​</a></h4><p>主要快捷键有：</p><ul><li><code>F1</code> = 拉下终端 Tilda（注意：如果你有多个配置文件，快捷方式是 F1、F2、F3 等）</li><li><code>F11</code> = 全屏模式</li><li><code>F12</code> = 切换透明模式</li><li><code>Ctrl+Shift+T</code> = 添加标签</li><li><code>Ctrl+Page Up</code> = 下一个标签</li><li><code>Ctrl+Page Down</code> = 上一个标签</li></ul><h3 id="gnome-扩展" tabindex="-1">GNOME 扩展 <a class="header-anchor" href="#gnome-扩展" aria-label="Permalink to “GNOME 扩展”">​</a></h3>',20)),i("p",null,[a[8]||(a[8]=e("Drop-down Terminal ",-1)),l(t,{href:"https://extensions.gnome.org/extension/442/drop-down-terminal/"},{default:s(()=>[...a[7]||(a[7]=[e("GNOME 扩展",-1)])]),_:1}),a[9]||(a[9]=e("允许你在 GNOME Shell 中使用这个有用的工具。它易于安装和配置，使你可以快速访问终端会话。",-1))]),a[33]||(a[33]=i("h4",{id:"安装",tabindex:"-1"},[e("安装 "),i("a",{class:"header-anchor",href:"#安装","aria-label":"Permalink to “安装”"},"​")],-1)),i("p",null,[a[11]||(a[11]=e("打开浏览器并转到",-1)),l(t,{href:"https://extensions.gnome.org/extension/442/drop-down-terminal/"},{default:s(()=>[...a[10]||(a[10]=[e("此 GNOME 扩展的站点",-1)])]),_:1}),a[12]||(a[12]=e("。启用扩展设置为“On”，如下所示：",-1))]),a[34]||(a[34]=o('<p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/gnome-shell-install_2-1024x455.png" alt=""></p><p>然后选择“Install”以在系统上安装扩展。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/gnome-shell-install_3.png" alt=""></p><p>执行此操作后，无需设置任何自动启动选项。只要你登录 GNOME，扩展程序就会自动运行！</p><h4 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h4><p>安装后，将打开 Drop-down Terminal 配置窗口以设置首选项。例如，可以设置终端大小、动画、透明度和使用滚动条。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/gnome-shell-install_4.png" alt=""></p><p>如果你将来需要更改某些首选项，请运行 <code>gnome-shell-extension-prefs</code> 命令并选择“Drop Down Terminal”。</p><h4 id="使用该扩展" tabindex="-1">使用该扩展 <a class="header-anchor" href="#使用该扩展" aria-label="Permalink to “使用该扩展”">​</a></h4><p>快捷键很简单：</p><ul><li>反尖号 （通常是 <code>Tab</code> 键上面的一个键) = 打开/撤回终端</li><li><code>F12</code> （可以定制） = 打开/撤回终端</li></ul><hr>',12)),i("p",null,[a[14]||(a[14]=e("via: ",-1)),l(t,{href:"https://fedoramagazine.org/use-a-drop-down-terminal-for-fast-commands-in-fedora/"},{default:s(()=>[...a[13]||(a[13]=[e("https://fedoramagazine.org/use-a-drop-down-terminal-for-fast-commands-in-fedora/",-1)])]),_:1})]),i("p",null,[a[19]||(a[19]=e("作者：",-1)),l(t,{href:"https://fedoramagazine.org/author/schelp/"},{default:s(()=>[...a[15]||(a[15]=[e("Guilherme Schelp",-1)])]),_:1}),a[20]||(a[20]=e(" 选题：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:s(()=>[...a[16]||(a[16]=[e("lujun9972",-1)])]),_:1}),a[21]||(a[21]=e(" 译者：",-1)),l(t,{href:"https://github.com/wxy"},{default:s(()=>[...a[17]||(a[17]=[e("wxy",-1)])]),_:1}),a[22]||(a[22]=e(" 校对：",-1)),l(t,{href:"https://github.com/wxy"},{default:s(()=>[...a[18]||(a[18]=[e("wxy",-1)])]),_:1})]),i("p",null,[a[25]||(a[25]=e("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...a[23]||(a[23]=[e("LCTT",-1)])]),_:1}),a[26]||(a[26]=e(" 原创编译，",-1)),l(t,{href:"https://linux.cn/"},{default:s(()=>[...a[24]||(a[24]=[e("Linux中国",-1)])]),_:1}),a[27]||(a[27]=e(" 荣誉推出",-1))])])}const c=n(g,[["render",u]]);export{C as __pageData,c as default};
